"use client"

import { useEffect, useRef, useState } from "react"

export type LissajousOrbitLoaderProps = {
  /** 0..1 for a known amount; leave undefined for an indeterminate loader. */
  progress?: number
  /** Heading under the orbit. */
  label?: string
  /** Lines that cycle under the heading while it loads. */
  steps?: string[]
  /** Diameter of the orbit stage in px. */
  size?: number
  /** Comet colours, one per head. */
  colors?: string[]
  /** Seconds each figure holds before morphing into the next. */
  hold?: number
  className?: string
}

const FONT =
  "@font-face{font-family:LolSans;src:url(data:font/woff2;base64,) format('woff2');font-weight:400 600;font-display:swap}" +
  "@font-face{font-family:LolMono;src:url(data:font/woff2;base64,) format('woff2');font-weight:500;font-display:swap}"

const CSS =
  FONT +
  ".lol-root{--lol-bg:#070914;--lol-text:#eef0ff;--lol-dim:#8a8fb3;display:flex;flex-direction:column;align-items:center;gap:22px;font-family:LolSans,ui-sans-serif,system-ui,sans-serif;animation:lol-rise .8s cubic-bezier(.2,.9,.25,1) both}" +
  ".lol-stage{position:relative;border-radius:50%;isolation:isolate;" +
  "background:radial-gradient(circle at 50% 40%,#16193a 0%,var(--lol-bg) 62%);box-shadow:0 0 0 1px rgba(255,255,255,.06) inset,0 1px 0 rgba(255,255,255,.1) inset,0 40px 80px -30px rgba(30,20,90,.7),0 0 0 10px rgba(120,110,255,.04),0 0 0 22px rgba(120,110,255,.025)}" +
  ".lol-stage::before{content:'';position:absolute;inset:8%;border-radius:50%;border:1px dashed rgba(170,170,255,.12);animation:lol-turn 40s linear infinite}" +
  ".lol-stage::after{content:'';position:absolute;inset:0;border-radius:50%;pointer-events:none;background:radial-gradient(circle at 30% 20%,rgba(255,255,255,.1),transparent 40%)}" +
  ".lol-canvas{position:absolute;inset:0;width:100%;height:100%;border-radius:50%}" +
  ".lol-center{position:absolute;inset:0;display:grid;place-items:center;pointer-events:none}" +
  ".lol-pct{font-family:LolMono,ui-monospace,monospace;font-size:13px;font-weight:500;letter-spacing:.08em;color:var(--lol-text);padding:6px 10px;border-radius:99px;background:rgba(7,9,20,.55);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);box-shadow:0 0 0 1px rgba(255,255,255,.08) inset;font-variant-numeric:tabular-nums}" +
  ".lol-ring{position:absolute;inset:-6px;width:calc(100% + 12px);height:calc(100% + 12px);transform:rotate(-90deg);pointer-events:none}" +
  ".lol-ring circle{transition:stroke-dashoffset .6s cubic-bezier(.2,.8,.2,1)}" +
  ".lol-copy{text-align:center;min-height:44px}" +
  ".lol-h{margin:0;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--color-foreground,#111)}" +
  ".lol-step{display:block;margin-top:4px;font-family:LolMono,ui-monospace,monospace;font-size:12px;color:var(--color-muted-foreground,#777);animation:lol-step .5s cubic-bezier(.2,.9,.25,1) both}" +
  ".lol-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}" +
  "@keyframes lol-rise{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}" +
  "@keyframes lol-turn{to{transform:rotate(360deg)}}" +
  "@keyframes lol-step{from{opacity:0;transform:translateY(6px);filter:blur(3px)}to{opacity:1;transform:none;filter:none}}" +
  "@media (prefers-reduced-motion:reduce){.lol-root,.lol-stage::before,.lol-step{animation:none!important}.lol-ring circle{transition:none}}"

// #region curves
export type Figure = { kind: "lissajous" | "rose" | "trochoid"; a: number; b: number; c: number }

export const FIGURES: Figure[] = [
  { kind: "lissajous", a: 3, b: 2, c: Math.PI / 2 },
  { kind: "rose", a: 5, b: 3, c: 0 },
  { kind: "trochoid", a: 5, b: 3, c: 2.6 },
  { kind: "lissajous", a: 5, b: 4, c: Math.PI / 2 },
  { kind: "rose", a: 7, b: 4, c: 0 },
]

/** Point on a figure at parameter t, in roughly [-1, 1]. */
export function point(f: Figure, t: number): [number, number] {
  if (f.kind === "lissajous") return [Math.sin(f.a * t + f.c), Math.sin(f.b * t)]
  if (f.kind === "rose") {
    // Rose with k = a/b; t is scaled so one loop of t (2π) closes the figure.
    const s = t * f.b
    const r = Math.cos((f.a / f.b) * s)
    return [r * Math.cos(s), r * Math.sin(s)]
  }
  // Hypotrochoid with R = a, r = b, pen distance c, normalised to fit.
  const R = f.a
  const r = f.b
  const s = t * r
  const k = (R - r) / r
  const x = (R - r) * Math.cos(s) + f.c * Math.cos(k * s)
  const y = (R - r) * Math.sin(s) - f.c * Math.sin(k * s)
  const m = R - r + f.c
  return [x / m, y / m]
}

export const easeInOut = (x: number) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2)

/** Which two figures are on screen at time `sec`, and how far the morph between them has gone. */
export function morphAt(sec: number, hold: number, morph: number, count: number) {
  const span = hold + morph
  const i = Math.floor(sec / span)
  const local = sec - i * span
  const m = local < hold ? 0 : easeInOut((local - hold) / morph)
  return { from: ((i % count) + count) % count, to: (((i + 1) % count) + count) % count, m }
}

export function blend(a: Figure, b: Figure, m: number, t: number): [number, number] {
  const p = point(a, t)
  if (m <= 0) return p
  const q = point(b, t)
  return [p[0] + (q[0] - p[0]) * m, p[1] + (q[1] - p[1]) * m]
}
// #endregion

const COLORS = ["#8b7bff", "#3ee0ff", "#ff6ad5"]
const STEPS = ["Compiling shaders", "Uploading textures", "Baking light", "Warming caches", "Almost there"]

export default function LissajousOrbitLoader({
  progress,
  label = "Rendering your scene",
  steps = STEPS,
  size = 240,
  colors = COLORS,
  hold = 2.4,
  className = "",
}: LissajousOrbitLoaderProps) {
  const canvas = useRef(null as HTMLCanvasElement | null)
  const known = typeof progress === "number"
  const pct = known ? Math.max(0, Math.min(1, progress as number)) : 0
  const [step, setStep] = useState(0)
  // The frame loop reads colours from a ref so a new array literal doesn't restart it.
  const cols = useRef(colors)
  cols.current = colors
  const colorKey = colors.join()

  useEffect(() => {
    if (steps.length < 2) return
    const t = setInterval(() => setStep((s) => (s + 1) % steps.length), 1800)
    return () => clearInterval(t)
  }, [steps.length])

  useEffect(() => {
    const cv = canvas.current
    const ctx = cv?.getContext("2d")
    if (!cv || !ctx) return
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)")
    // Size is measured by the observer only; the frame loop reads these cached numbers.
    let w = size
    let dpr = Math.min(2, window.devicePixelRatio || 1)
    const fit = () => {
      cv.width = Math.round(w * dpr)
      cv.height = Math.round(w * dpr)
    }
    fit()
    const ro = new ResizeObserver(([e]) => {
      w = e.contentRect.width || size
      dpr = Math.min(2, window.devicePixelRatio || 1)
      fit()
      if (reduced.matches) draw(0)
    })
    ro.observe(cv)

    const SEG = 56
    const TRAIL = 1.35
    const GUIDE = 260
    let raf = 0
    let start = 0
    let running = true

    const draw = (ms: number) => {
      const sec = reduced.matches ? 0 : ms / 1000
      const { from, to, m } = morphAt(sec, hold, 1.1, FIGURES.length)
      const A = FIGURES[from]
      const B = FIGURES[to]
      const W = w * dpr
      const R = W * 0.36
      const cx = W / 2
      const cy = W / 2
      ctx.setTransform(1, 0, 0, 1, 0, 0)
      ctx.clearRect(0, 0, W, W)

      // The faint guide: the whole current figure.
      ctx.beginPath()
      for (let i = 0; i <= GUIDE; i++) {
        const [x, y] = blend(A, B, m, (i / GUIDE) * Math.PI * 2)
        if (i) ctx.lineTo(cx + x * R, cy + y * R)
        else ctx.moveTo(cx + x * R, cy + y * R)
      }
      ctx.strokeStyle = "rgba(170,175,255,.13)"
      ctx.lineWidth = 1 * dpr
      ctx.stroke()

      ctx.globalCompositeOperation = "lighter"
      ctx.lineCap = "butt"
      const speed = 0.9
      const list = cols.current
      list.forEach((col, h) => {
        const head = sec * speed + (h / list.length) * Math.PI * 2
        // Trail: short segments that thin and fade towards the tail.
        let [px, py] = blend(A, B, m, head - TRAIL)
        for (let s = 1; s <= SEG; s++) {
          const u = s / SEG
          const [x, y] = blend(A, B, m, head - TRAIL * (1 - u))
          ctx.beginPath()
          ctx.moveTo(cx + px * R, cy + py * R)
          ctx.lineTo(cx + x * R, cy + y * R)
          ctx.strokeStyle = col
          ctx.globalAlpha = u * u * 0.9
          ctx.lineWidth = (0.6 + u * 2.6) * dpr
          ctx.stroke()
          px = x
          py = y
        }
        // Head with a soft halo.
        const hx = cx + px * R
        const hy = cy + py * R
        const g = ctx.createRadialGradient(hx, hy, 0, hx, hy, 16 * dpr)
        g.addColorStop(0, col)
        g.addColorStop(1, "transparent")
        ctx.globalAlpha = 0.85
        ctx.fillStyle = g
        ctx.beginPath()
        ctx.arc(hx, hy, 16 * dpr, 0, Math.PI * 2)
        ctx.fill()
        ctx.globalAlpha = 1
        ctx.fillStyle = "#fff"
        ctx.beginPath()
        ctx.arc(hx, hy, 2.2 * dpr, 0, Math.PI * 2)
        ctx.fill()
      })
      ctx.globalCompositeOperation = "source-over"
      ctx.globalAlpha = 1
    }

    const loop = (now: number) => {
      if (!running) return
      if (!start) start = now
      draw(now - start)
      raf = requestAnimationFrame(loop)
    }
    const go = () => {
      cancelAnimationFrame(raf)
      if (reduced.matches) draw(0)
      else raf = requestAnimationFrame(loop)
    }
    // Stop drawing while the tab is hidden.
    const vis = () => {
      running = !document.hidden
      if (running) go()
      else cancelAnimationFrame(raf)
    }
    go()
    reduced.addEventListener("change", go)
    document.addEventListener("visibilitychange", vis)
    return () => {
      running = false
      cancelAnimationFrame(raf)
      ro.disconnect()
      reduced.removeEventListener("change", go)
      document.removeEventListener("visibilitychange", vis)
    }
  }, [size, hold, colorKey])

  const C = 2 * Math.PI * 49
  return (
    <div
      className={"lol-root " + className}
      role="progressbar"
      aria-label={label}
      aria-valuemin={known ? 0 : undefined}
      aria-valuemax={known ? 100 : undefined}
      aria-valuenow={known ? Math.round(pct * 100) : undefined}
      aria-valuetext={known ? Math.round(pct * 100) + "%" : steps[step] || "Loading"}
      aria-busy={!known || pct < 1}
    >
      <style>{CSS}</style>
      <div className="lol-stage" style={{ width: size, height: size }}>
        <canvas ref={canvas} className="lol-canvas" width={size} height={size} aria-hidden="true" />
        {known && (
          <svg className="lol-ring" viewBox="0 0 100 100" aria-hidden="true">
            <defs>
              <linearGradient id="lol-g" x1="0" y1="0" x2="1" y2="1">
                <stop offset="0" stopColor={colors[0]} />
                <stop offset="1" stopColor={colors[1] || colors[0]} />
              </linearGradient>
            </defs>
            <circle cx="50" cy="50" r="49" fill="none" stroke="rgba(160,160,255,.12)" strokeWidth="1" />
            <circle cx="50" cy="50" r="49" fill="none" stroke="url(#lol-g)" strokeWidth="1.6" strokeLinecap="round" strokeDasharray={C} strokeDashoffset={C * (1 - pct)} />
          </svg>
        )}
        {known && (
          <span className="lol-center" aria-hidden="true">
            <span className="lol-pct">{String(Math.round(pct * 100)).padStart(2, "0")}%</span>
          </span>
        )}
      </div>
      <div className="lol-copy" aria-hidden="true">
        <p className="lol-h">{label}</p>
        {steps.length > 0 && (
          <span className="lol-step" key={step}>
            {steps[step]}
          </span>
        )}
      </div>
    </div>
  )
}
